class Solution {
  public int countSpecialSubsequences(int[] nums) {
    final long MOD = 1_000_000_007L;
    long[] dp = new long[3];
    for (int x : nums) {
      if (x == 0) dp[0] = (2 * dp[0] + 1) % MOD;
      else if (x == 1) dp[1] = (2 * dp[1] + dp[0]) % MOD;
      else dp[2] = (2 * dp[2] + dp[1]) % MOD;
    }
    return (int) dp[2];
  }
}
